/// Starts the GUI.
pub fn run_gui() -> eframe::Result<()> {
    use eframe::egui;
    // 64×64 RGBA, generated by installer/make-icon.ps1
    let icon = egui::IconData { rgba: include_bytes!("../installer/icon64.rgba").to_vec(), width: 64, height: 64 };
    let options = eframe::NativeOptions {
        viewport: egui::ViewportBuilder::default()
            .with_inner_size([1560.0, 940.0])
            .with_title("Lampdesigner")
            .with_icon(icon),
        ..Default::default()
    };
    eframe::run_native("Lampdesigner", options, Box::new(|cc| Ok(Box::new(app::App::new(cc)))))
}
